"""Native MCP finalizer; run only after asset setup and table registration."""
import json
ASSETS = json.loads("[\"/Game/Skills/LavaEruption/BP_LavaEruption\",\"/Game/Skills/LavaEruption/Meshes/SM_LavaEruption\",\"/Game/Skills/LavaEruption/Materials/M_LavaEruption_Facet\",\"/Game/Skills/LavaEruption/Materials/M_LavaEruption_Edge\",\"/Game/Skills/LavaEruption/Materials/M_LavaEruption_Core\",\"/Game/Skills/LavaEruption/Effects/NS_LavaEruption_Trail\",\"/Game/Skills/LavaEruption/Effects/NS_LavaEruption_Impact\",\"/Game/Skills/LavaEruption/Icons/T_LavaEruption\",\"/Game/Skills/LavaEruption/Icons/T_LavaEruption_Area\",\"/Game/Skills/LavaEruption/Icons/T_LavaEruption_Cooldown\",\"/Game/Skills/LavaEruption/Icons/T_LavaEruption_Mana\",\"/Game/Skills/ArcScatter/BP_ArcScatter\",\"/Game/Skills/ArcScatter/Meshes/SM_ArcScatter\",\"/Game/Skills/ArcScatter/Materials/M_ArcScatter_Facet\",\"/Game/Skills/ArcScatter/Materials/M_ArcScatter_Edge\",\"/Game/Skills/ArcScatter/Materials/M_ArcScatter_Core\",\"/Game/Skills/ArcScatter/Effects/NS_ArcScatter_Trail\",\"/Game/Skills/ArcScatter/Effects/NS_ArcScatter_Impact\",\"/Game/Skills/ArcScatter/Icons/T_ArcScatter\",\"/Game/Skills/ArcScatter/Icons/T_ArcScatter_Multiple\",\"/Game/Skills/ArcScatter/Icons/T_ArcScatter_Pierce\",\"/Game/Skills/ArcScatter/Icons/T_ArcScatter_Fork\",\"/Game/Skills/FrostRush/BP_FrostRush\",\"/Game/Skills/FrostRush/Meshes/SM_FrostRush\",\"/Game/Skills/FrostRush/Materials/M_FrostRush_Facet\",\"/Game/Skills/FrostRush/Materials/M_FrostRush_Edge\",\"/Game/Skills/FrostRush/Materials/M_FrostRush_Core\",\"/Game/Skills/FrostRush/Effects/NS_FrostRush_Trail\",\"/Game/Skills/FrostRush/Effects/NS_FrostRush_Impact\",\"/Game/Skills/FrostRush/Icons/T_FrostRush\",\"/Game/Skills/FrostRush/Icons/T_FrostRush_Area\",\"/Game/Skills/FrostRush/Icons/T_FrostRush_Freeze\",\"/Game/Skills/FrostRush/Icons/T_FrostRush_Cooldown\",\"/Game/Skills/FrostRush/GE_FrostRush_Slow\",\"/Game/Skills/FrostRush/GE_FrostRush_Freeze\"]")
TABLES = ["/Game/Datatable/" + name for name in ["DT_GASSkillData", "DT_SkillVariantion", "DT_JobSkillSet"]]
def run():
    result = execute_tool("editor_toolset.toolsets.asset.AssetTools.save_assets", json.dumps({"asset_paths": ASSETS + TABLES}))
    assert result["returnValue"], "Asset saving failed"
    dirty = []
    for path in ASSETS + TABLES:
        if execute_tool("editor_toolset.toolsets.asset.AssetTools.is_dirty", json.dumps({"asset_path": path}))["returnValue"]:
            dirty.append(path)
    return {"saved": not dirty, "asset_count": len(ASSETS), "table_count": len(TABLES), "dirty": dirty}
